5	/// The "Open in…" editor control for a selected target: a menu whose primary action reopens in the
6	/// last-picked editor. A plain `View` (not `ToolbarContent`) so it composes into the title-bar
7	/// toolbar (`TrailingTitlebarBar`) as a sibling of the other controls, sharing its `.borderless`
8	/// button style. (Renders nothing when no editors are installed.)
9	struct OpenInControl: View {
10	  let path: String
11	
12	  /// Bundle id of the last editor picked from the "Open in…" menu — the primary action reopens in it.
13	  @Default(.lastEditor) private var lastEditorID
14	
15	  var body: some View {
16	    let editors = ExternalEditor.installed
17	    if !editors.isEmpty {
18	      let remembered = editors.first { $0.id == lastEditorID } ?? editors[0]
19	      // Two SEPARATE controls in one tight group: an icon Button that opens in the remembered editor
20	      // on a single click (also ⇧⌘O / the Go-menu item), and a chevron Menu to pick a different one.
21	      // Both inherit the bar's `ToolbarIconButtonStyle`, so each gets its own hover well. Negative
22	      // spacing pulls the two 22pt-min wells together so the small chevron sits snug against the icon
23	      // (each well only paints on its own hover, so the slight overlap never shows two at once).
24	      HStack(spacing: -8) {
25	        Button {
26	          remembered.open(path)
27	        } label: {
28	          Image(systemName: "arrow.up.forward.app")
29	            .hidden()
30	            .overlay {
31	              Image(nsImage: remembered.icon).renderingMode(.original).resizable().scaledToFit()
32	            }
33	            .frame(width: 16, height: 16)
34	        }
35	        .help("Open in \(remembered.name) (⇧⌘O)")
36	        .accessibilityLabel("Open in \(remembered.name)")
37	
38	        Menu {
39	          ForEach(editors) { editor in
40	            Button {
41	              lastEditorID = editor.id
42	              editor.open(path)
43	            } label: {
44	              Label {
45	                Text(editor.name)
46	              } icon: {
47	                Image(nsImage: editor.icon).renderingMode(.original)
48	              }
49	            }
50	          }
51	        } label: {
52	          Image(systemName: "chevron.down")
53	            .font(.system(size: 8, weight: .semibold))
54	            .foregroundStyle(.secondary)
55	        }
56	        .menuStyle(.button)
57	        // We draw the chevron ourselves, so hide the system disclosure indicator.
58	        .menuIndicator(.hidden)
59	        .fixedSize()
60	        .help("Open in… (choose editor)")
61	        .accessibilityLabel("Choose editor")
62	      }
63	    }
64	  }
