90	        Button {
91	          store.restartRunCommand(for: target)
92	        } label: {
93	          Image(systemName: "arrow.clockwise")
94	        }
95	        .help("Restart the run command (⌥⌘R)")
96	        .accessibilityLabel("Restart")
97	        .accessibilityIdentifier("runCommand.restart")
98	      } else {
99	        // Not running (no run tab, or stopped-but-open). `runOrFocusRunCommand` acts on the
