3	/// The shared right-click menu items for a workroom, reused by the tab chip
4	/// (`WorkroomTabBar`) and the split group title bar (`WorkroomSplitView`) — issue #112. One
5	/// source of truth so the two menus can't drift.
6	///
7	/// `closeName != nil` renders the "Close" item (close the whole workroom — all its terminal
8	/// tabs — the files stay) with that display name.
9	///
10	/// `onRemoveFromSplit != nil` renders a "Remove from Split" item that pops this workroom out of the
11	/// split (keeps it running) — the menu equivalent of the title bar's `pip.exit` ✕. Only the split
12	/// title bar passes it; the tab chip passes `nil` (a tab isn't a split member).
13	///
14	/// Label + Delete apply only to a real workroom (roots are never labelled or deletable), gated
15	/// on `store.workroomAndProject(for:)`.
16	///
17	/// Each item sets a store flag that `RootView`'s `.confirmationDialog`/`.sheet` bridge observes
18	/// (the store-flag → dialog pattern), except "Remove Label"/"Remove from Split" which act immediately.
19	///
20	/// `@MainActor` because it touches the main-actor `AppStore`; the callers' `.contextMenu` closures
21	/// are already main-actor-isolated (they live in `View.body`), so this is a no-op at the call site.
22	@MainActor
23	@ViewBuilder
24	func workroomContextMenu(
25	  store: AppStore, sid: SidebarID, target: TerminalTarget, closeName: String?,
26	  onRemoveFromSplit: (() -> Void)? = nil
27	) -> some View {
28	  if let closeName {
29	    // Close the whole workroom (all its tabs); the workroom's files stay. Confirmed via
30	    // RootView's `pendingWorkroomClose` dialog.
31	    Button {
32	      store.pendingWorkroomClose = PendingWorkroomClose(target: target, name: closeName)
33	    } label: {
34	      Label("Close", systemImage: "xmark")
35	    }
36	  }
37	  if let onRemoveFromSplit {
38	    // Pop this workroom out of the split (it keeps running) — same action as the title bar's ✕
39	    // (`pip.exit`). Acts immediately; no confirmation.
40	    Button {
41	      onRemoveFromSplit()
42	    } label: {
43	      Label("Remove from Split", systemImage: "pip.exit")
44	    }
45	  }
46	  // Label + delete only apply to a workroom (roots are never labelled or deletable). Mirrors the
47	  // sidebar row's context menu (issue #41 + delete).
48	  if let pair = store.workroomAndProject(for: sid) {
49	    // Leading divider only when a top item (Close / Remove from Split) was shown above.
50	    if closeName != nil || onRemoveFromSplit != nil { Divider() }
51	    Button {
52	      store.pendingWorkroomLabel = PendingWorkroomLabel(
53	        workroom: pair.workroom, project: pair.project)
54	    } label: {
55	      Label(pair.workroom.label == nil ? "Set Label…" : "Edit Label…", systemImage: "pencil")
56	    }
57	    if pair.workroom.label != nil {
58	      Button {
59	        store.removeWorkroomLabel(pair.workroom, in: pair.project)
60	      } label: {
61	        Label("Remove Label", systemImage: "pencil.slash")
62	      }
63	    }
64	    Divider()
65	    Button(role: .destructive) {
66	      store.pendingDeletion = PendingWorkroomDeletion(
67	        workroom: pair.workroom, project: pair.project)
68	    } label: {
69	      Label("Delete Workroom…", systemImage: "trash")
70	    }
71	    // Can't delete a workroom while its setup is still running against the worktree (issue #116).
72	    .disabled(store.isCreatingWorkroom(pair.workroom, in: pair.project))
73	  }
74	}
