          // first-responder → selection callback (the libghostty NSView eats SwiftUI taps).
          .onTapGesture { onFocus(sid) }
        }
      }
      ForEach(plan.dividers) { d in
        WorkroomSplitDivider(
          orientation: d.orientation, ratio: d.ratio, total: d.total,
