import XCTest

@testable import Workroom

/// The workroom pane title bar's trailing-control matrix (issue #139), kept pure and tested away from
/// SwiftUI for the same reason `WorkroomSplitTitlePresentation` is: the three rules are easy to state
/// and easy to get subtly wrong in a view body, and a view can't be instantiated in a unit test.
final class WorkroomPaneToolbarPresentationTests: XCTestCase {
  private func controls(isMissing: Bool = false, projectPath: String? = "/a", multi: Bool = false)
    -> WorkroomPaneToolbarPresentation.Controls
  {
    WorkroomPaneToolbarPresentation.controls(
      isMissing: isMissing, projectPath: projectPath, multi: multi)
  }

  /// The common case — a healthy solo workroom — shows both actions and no way out of a split.
  func testSoloHealthyWorkroomShowsOpenInAndRunButNoClose() {
    XCTAssertEqual(
      controls(),
      .init(openIn: true, run: true, removeFromSplit: false))
  }

  /// A vanished directory has nothing to open in an editor and nothing to run in. Leaving both visible
  /// would offer actions that can only fail.
  func testMissingDirectoryHidesBothActions() {
    let c = controls(isMissing: true)
    XCTAssertFalse(c.openIn)
    XCTAssertFalse(c.run)
  }

  /// Run needs an owning project to look its command up in (`Defaults[.runCommands]` is keyed by
  /// project path). "Open in…" only needs the target's own path, so it survives.
  func testNoProjectPathHidesRunButKeepsOpenIn() {
    let c = controls(projectPath: nil)
    XCTAssertTrue(c.openIn)
    XCTAssertFalse(c.run)
  }

  /// The ✕ is the one control that is genuinely split-only: a solo pane has no group to leave.
  func testRemoveFromSplitTracksMembershipOnly() {
    XCTAssertTrue(controls(multi: true).removeFromSplit)
    XCTAssertFalse(controls(multi: false).removeFromSplit)
    // …and it is independent of the actions, so a missing member can still be popped out of a split —
    // which is the only way to get rid of a "Directory not found" pane.
    XCTAssertTrue(controls(isMissing: true, multi: true).removeFromSplit)
  }
}

